import{_ as l,a0 as i,w as p,s as u,I as n,x as e,a1 as o,A as r,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"開源 vs. 閉源 | LCTT x X-CMD","titleTemplate":false,"description":"開源 vs. 閉源 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開源 vs. 閉源 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開源 vs. 閉源 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161104 Open Source Vs Closed Source","title":"開源 vs. 閉源","tag":"201611","desc":""},"relativePath":"201611/20161104 Open Source Vs Closed Source.md","filePath":"[post].md"}'),d={name:"201611/20161104 Open Source Vs Closed Source.md"};function m(h,t,f,x,b,g){const a=i("Link");return p(),u("div",null,[t[18]||(t[18]=n("h1",{id:"開源-vs-閉源",tabindex:"-1"},[e("開源 vs. 閉源 "),n("a",{class:"header-anchor",href:"#開源-vs-閉源","aria-label":"Permalink to “開源 vs. 閉源”"},"​")],-1)),n("p",null,[o(a,{href:"http://www.linuxandubuntu.com/home/open-source-vs-closed-source"},{default:r(()=>[...t[0]||(t[0]=[n("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/open-source-vs-closed-source_orig.jpg",alt:"開源 vs. 閉源"},null,-1)])]),_:1})]),t[19]||(t[19]=n("p",null,[n("strong",null,"開源操作系統"),e("和"),n("strong",null,"閉源操作系統"),e("之間有諸多不同。這裏我們僅寥書幾筆。")],-1)),t[20]||(t[20]=n("h3",{id:"開源是什麼-自由",tabindex:"-1"},[e("開源是什麼？自由！ "),n("a",{class:"header-anchor",href:"#開源是什麼-自由","aria-label":"Permalink to “開源是什麼？自由！”"},"​")],-1)),n("p",null,[o(a,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/what-is-open-source_orig.jpg?250"},{default:r(()=>[...t[1]||(t[1]=[n("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/what-is-open-source.jpg?250",alt:"開源是什麼？"},null,-1)])]),_:1})]),t[21]||(t[21]=s('<p>這是用户需要知道的最重要的一點。無論我是否打算修改代碼，其他人出於善意的修改都不應受到限制。且如果用户喜歡，他們可以分享這個軟件。使用<strong>開源</strong>軟件，這些都是可能的。</p><p><strong>閉源</strong>操作系統的許可條款很是嚇人。但真的所有人都會看嗎？不，許多用户只是點了一下‘Accept’ 而已。</p><h3 id="價格" tabindex="-1">價格 <a class="header-anchor" href="#價格" aria-label="Permalink to “價格”">​</a></h3><p>幾乎所有的開源操縱系統是免費的。僅有自願性質的捐款。且只需有個一個 <strong>CD/DVD 或 USB</strong> 就能將系統安裝到所有你想要安裝的電腦上。</p><p>閉源操作系統相較於開源 OS 就貴了許多，如果你用它來構建 PC，每台 PC 得你花不少於 $100。</p><p>我們可以用花在閉源軟件上的錢去買更好的東西。</p><h3 id="選擇" tabindex="-1">選擇 <a class="header-anchor" href="#選擇" aria-label="Permalink to “選擇”">​</a></h3><p>開源操作系統的發行版有很多。如果你不中意眼下的這個，你可以嘗試其他的發行版，總能找到適合你的那一個。</p><p>諸如 Ubuntu studio、Bio Linux、Edubuntu、Kali Linux、Qubes、SteamOS 這些發行版，就是針對特定用户羣產生的發行版。</p><p>閉源軟件有“選擇”這種説法嗎？我覺得是沒有的。</p><h3 id="隱私" tabindex="-1">隱私 <a class="header-anchor" href="#隱私" aria-label="Permalink to “隱私”">​</a></h3><p><strong>開源操作系統</strong>無需收集用户數據信息。不會根據用户的個性顯示廣告，也不會把你的信息賣給第三方機構。如果開發者需要資金，他們會要求捐助，或是在他們的網頁上打廣告。廣告的內容也會與 Linux 相關，對我們有益無害。</p><p>你一定知道那個主流的閉源操作系統（名字就不寫了，大家都知道的），據説因為收集用户信息這件事，導致多數用户關閉了他們的免費更新服務。多數該系統的用户為了避免升級，將更新功能關閉，他們寧可承擔安全風險也不要免費更新。</p><h3 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h3><p>開源軟件大多安全。究其緣由不僅有市場佔有率低這個原因，其本身的構成方式就比較安全。例如， Qubes Os 是最安全的操作系統之一，它將運行的軟件相互隔離。</p><p>閉源操作系統向易用性妥協，使其變得愈發脆弱。</p><h3 id="硬件支持" tabindex="-1">硬件支持 <a class="header-anchor" href="#硬件支持" aria-label="Permalink to “硬件支持”">​</a></h3>',17)),n("p",null,[t[3]||(t[3]=e("我們中有大多數人，家裏還放着那些不想丟的舊 PC，這時一個輕量級的發行版可能會讓這些老傢伙們重獲新生。你可以試試在文章 ",-1)),o(a,{href:"http://www.linuxandubuntu.com/home/5-lightweight-linux-for-old-computers"},{default:r(()=>[...t[2]||(t[2]=[e("5 個適合舊電腦的輕量級 Linux",-1)])]),_:1}),t[4]||(t[4]=e(" 中羅列的那些輕量級操作系統發行版。基於 Linux 的系統幾乎包含所有設備的驅動，所以基本不需要你親自尋找、安裝驅動。",-1))]),t[22]||(t[22]=s('<p>閉源操作系統時不時中止對舊硬件的支持，迫使用户去購買新的硬件。我們還不得不親自尋找、安裝驅動。</p><h3 id="社區支持" tabindex="-1">社區支持 <a class="header-anchor" href="#社區支持" aria-label="Permalink to “社區支持”">​</a></h3><p>幾乎所有的<strong>開源操作系統</strong>都有用户論壇，你可以在那裏提問題，並從別的用户那裏得到答案。大家在那裏分享技巧和竅門，互幫互助。有經驗的 Linux 用户往往樂於幫助新手，為此他們常常不遺餘力。</p><p><strong>閉源操作系統</strong>社區和開源操作系統社區簡直無法相提並論。提出的問題常常得不到回答。</p><h3 id="商業化" tabindex="-1">商業化 <a class="header-anchor" href="#商業化" aria-label="Permalink to “商業化”">​</a></h3><p>在操作系統上掙錢是非常困難的。（開源）開發者一般通過用户的捐款和在網站上打廣告來掙錢。捐款主要用於支付主機的開銷和開發者的薪水。</p><p>許多閉源操作系統，不僅僅通過出售軟件的使用許可這種方式來賺錢，還會推送廣告大賺一票。</p><h3 id="垃圾應用" tabindex="-1">垃圾應用 <a class="header-anchor" href="#垃圾應用" aria-label="Permalink to “垃圾應用”">​</a></h3><p>我承認有些開源操作系統會提供一些我們可能一輩子都不會用到的應用，有些人認為他們是垃圾應用。但是也有發行版只提供最小安裝，其中就不包含這些不想要的軟件。所以，這不是真正的問題。</p><p>而所有的閉源操作系統中都包含廠商安裝的垃圾應用，強制你安裝，就像在安裝一個乾淨系統一樣。</p><p>開源軟件更像是一門哲學。一種分享和學習的方式。甚至還有益於經濟。</p><p>我們已經將我們知曉的羅列了出來。如果你覺得我們還漏了些什麼，可以評論告訴我們。</p><hr>',13)),n("p",null,[t[6]||(t[6]=e("via: ",-1)),o(a,{href:"http://www.linuxandubuntu.com/home/open-source-vs-closed-source"},{default:r(()=>[...t[5]||(t[5]=[e("http://www.linuxandubuntu.com/home/open-source-vs-closed-source",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=e("作者：",-1)),o(a,{href:"https://www.linkedin.com/in/mohdsohail"},{default:r(()=>[...t[7]||(t[7]=[e("Mohd Sohail",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),o(a,{href:"https://github.com/martin2011qi"},{default:r(()=>[...t[8]||(t[8]=[e("martin2011qi",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),o(a,{href:"https://github.com/jasminepeng"},{default:r(()=>[...t[9]||(t[9]=[e("jasminepeng",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=e("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創編譯，",-1)),o(a,{href:"https://linux.cn/"},{default:r(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const S=l(d,[["render",m]]);export{C as __pageData,S as default};
